:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --card-back: #0f3460;
  --card-border: #e94560;
  --focus: #f9c74f;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 30% 20%, #1f2b4d, var(--bg) 80%);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.game-wrapper {
  width: 100%;
  max-width: 520px;
  background: var(--surface);
  border-radius: 20px;
  padding: 24px 20px 28px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.game-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 1px;
  color: var(--primary);
}

.moves {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  width: 100%;
  max-width: 440px;
  aspect-ratio: 4 / 4;
}

.card {
  position: relative;
  border: 3px solid var(--card-border);
  border-radius: 8px;
  background: var(--card-back);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font: inherit;
  color: transparent;
  outline: none;
  image-rendering: pixelated;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.06);
}

.card::after {
  content: "?";
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--text);
  opacity: 0.7;
}

.card:hover:not(.flipped):not(.matched) {
  transform: translateY(-3px);
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.4);
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card:active:not(.flipped):not(.matched) {
  transform: scale(0.96);
}

.card.flipped,
.card.matched {
  background: var(--card-color, #888);
  border-color: #fff;
  cursor: default;
  transform: none;
}

.card.flipped::after,
.card.matched::after {
  content: "";
}

.card.matched {
  box-shadow: 0 0 0 3px var(--focus);
  opacity: 0.9;
}

.controls {
  display: flex;
  justify-content: center;
  width: 100%;
}

.btn {
  font-family: var(--font);
  font-size: 1.1rem;
  font-weight: 600;
  padding: 12px 32px;
  border: none;
  border-radius: 999px;
  background: var(--primary);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 0 #a12b3f;
}

.btn:hover {
  background: #f25c74;
}

.btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #a12b3f;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.win-message {
  text-align: center;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--focus);
  animation: pop 0.4s ease;
}

@keyframes pop {
  0% { transform: scale(0.7); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

@media (max-width: 400px) {
  body { font-size: 16px; padding: 10px; }
  .game-wrapper { padding: 18px 12px 22px; gap: 16px; }
  h1 { font-size: 1.35rem; }
  .game-board { gap: 8px; }
  .card::after { font-size: 1.2rem; }
  .btn { padding: 10px 26px; font-size: 1rem; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

(function () {
  'use strict';

  const COLORS = [
    '#e94560', '#f9c74f', '#43aa8b', '#577590',
    '#f9844a', '#9b5de5', '#00bbf9', '#f15bb5'
  ];

  const boardEl = document.getElementById('game-board');
  const moveCountEl = document.getElementById('move-count');
  const newGameBtn = document.getElementById('new-game');
  const winMessageEl = document.getElementById('win-message');

  let deck = [];
  let firstCard = null;
  let secondCard = null;
  let lockBoard = false;
  let moves = 0;
  let matchedPairs = 0;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const pairs = COLORS.flatMap((color, i) => [
      { id: i, color },
      { id: i, color }
    ]);
    return shuffle(pairs);
  }

  function buildBoard() {
    boardEl.innerHTML = '';
    deck.forEach((cardData, index) => {
      const btn = document.createElement('button');
      btn.className = 'card';
      btn.type = 'button';
      btn.dataset.id = cardData.id;
      btn.dataset.index = index;
      btn.style.setProperty('--card-color', cardData.color);
      btn.setAttribute('aria-label', 'Hidden card');
      btn.setAttribute('aria-pressed', 'false');
      btn.addEventListener('click', handleCardClick);
      boardEl.appendChild(btn);
    });
  }

  function handleCardClick(e) {
    const card = e.currentTarget;
    if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) return;

    flipCard(card);

    if (!firstCard) {
      firstCard = card;
      return;
    }

    secondCard = card;
    lockBoard = true;
    moves++;
    moveCountEl.textContent = moves;
    checkMatch();
  }

  function flipCard(card) {
    card.classList.add('flipped');
    card.setAttribute('aria-pressed', 'true');
    card.setAttribute('aria-label', 'Revealed card');
  }

  function unflipCard(card) {
    card.classList.remove('flipped');
    card.setAttribute('aria-pressed', 'false');
    card.setAttribute('aria-label', 'Hidden card');
  }

  function checkMatch() {
    const isMatch = firstCard.dataset.id === secondCard.dataset.id;

    if (isMatch) {
      firstCard.classList.add('matched');
      secondCard.classList.add('matched');
      firstCard.setAttribute('aria-label', 'Matched card');
      secondCard.setAttribute('aria-label', 'Matched card');
      firstCard.disabled = true;
      secondCard.disabled = true;
      matchedPairs++;
      resetTurn();
      if (matchedPairs === COLORS.length) {
        winMessageEl.hidden = false;
      }
    } else {
      setTimeout(() => {
        unflipCard(firstCard);
        unflipCard(secondCard);
        resetTurn();
      }, 750);
    }
  }

  function resetTurn() {
    firstCard = null;
    secondCard = null;
    lockBoard = false;
  }

  function newGame() {
    deck = createDeck();
    moves = 0;
    matchedPairs = 0;
    firstCard = null;
    secondCard = null;
    lockBoard = false;
    moveCountEl.textContent = '0';
    winMessageEl.hidden = true;
    buildBoard();
  }

  newGameBtn.addEventListener('click', newGame);

  newGame();
})();
